const coordOutput = ($input.first().json.text || '').trim();
const inputText   = $('Record Start Time').item.json.input_text;
let fallback = false;
let plan = { worker_count: 1, decomposition_rationale: 'Parse fallback — using single worker', task_a: inputText, task_b: '', task_c: '' };

try {
  const m = coordOutput.match(/\{[\s\S]*\}/);
  if (m) {
    const parsed = JSON.parse(m[0]);
    if (parsed && typeof parsed.worker_count === 'number') { plan = parsed; }
    else { fallback = true; }
  } else { fallback = true; }
} catch(e) { fallback = true; }

plan.worker_count = Math.max(1, Math.min(3, Math.round(plan.worker_count || 1)));
if (!plan.task_a) plan.task_a = inputText;
plan.task_b = plan.task_b || '';
plan.task_c = plan.task_c || '';

return [{ json: {
  worker_count:               plan.worker_count,
  decomposition_rationale:    plan.decomposition_rationale || '',
  task_a:                     plan.task_a,
  task_b:                     plan.task_b,
  task_c:                     plan.task_c,
  coordinator_raw_output:     coordOutput,
  coordinator_token_estimate: Math.ceil(coordOutput.length / 4),
  parse_fallback_used:        fallback
}}];

const items     = $input.all();
const plan      = $('Parse Coordinator Plan').item.json;
const labels    = ['A', 'B', 'C'];
const taskKeys  = ['task_a', 'task_b', 'task_c'];

const workerOutputs = [];
items.forEach((item, i) => {
  if (!item.json.skipped) {
    const text   = (item.json.text || '').trim();
    const tokEst = Math.ceil(text.length / 4);
    workerOutputs.push({
      worker:         'Worker ' + labels[i],
      task_assigned:  plan[taskKeys[i]] || '',
      response:       text,
      token_estimate: tokEst
    });
  }
});

const skipped = items
  .filter(i => i.json.skipped)
  .map(i => i.json.worker || 'unknown');

const workerBlock = workerOutputs.map((w, i) =>
  '--- Worker ' + (i + 1) + ' (' + w.worker + ') ---\n' +
  'Task: ' + w.task_assigned + '\n\n' +
  'Response:\n' + w.response
).join('\n\n');

return [{ json: {
  worker_outputs:          workerOutputs,
  worker_outputs_text:     workerBlock,
  active_worker_count:     workerOutputs.length,
  skipped_workers:         skipped,
  worker_count_requested:  plan.worker_count,
  decomposition_rationale: plan.decomposition_rationale
}}];

