const endMs      = Date.now();
const startMs    = $('Record Start Time').item.json.start_time_ms;
const inputTok   = $('Record Start Time').item.json.input_token_estimate || 0;
const inputText  = $('Record Start Time').item.json.input_text;
const latMs      = endMs - startMs;

const plan       = $('Parse Coordinator Plan').item.json;
const filterData = $('Filter Skips + Collect').item.json;
const synthText  = ($input.first().json.text || '').trim();
const synthTok   = Math.ceil(synthText.length / 4);

const coordTok       = plan.coordinator_token_estimate || 0;
const workerOutputs  = filterData.worker_outputs || [];
const totalWorkerTok = workerOutputs.reduce((s, w) => s + (w.token_estimate || 0), 0);
const activeCnt      = filterData.active_worker_count || 0;

const totalInputTok  = inputTok + coordTok;
const totalOutputTok = coordTok + totalWorkerTok + synthTok;
const totalTok       = totalInputTok + totalOutputTok;

const llmCallsActual = 2 + activeCnt;
const llmCallsMax    = 5;

return [{ json: {

  user_prompt:  inputText,
  final_answer: synthText,

  metadata: {
    pattern:           'Centralised AI Orchestration',
    pattern_category:  'AI-Orchestrated Multi-Agent Pattern',
    run_timestamp:     new Date().toISOString(),
    model:             'qwen2.5:14b',
    model_provider:    'Ollama (local)',
    temperature:       'not_configurable_via_n8n_ollama_node',
    latency_ms:        latMs,
    latency_seconds:   parseFloat((latMs / 1000).toFixed(2)),
    llm_calls_actual:  llmCallsActual,
    llm_calls_max:     llmCallsMax,
    token_usage: {
      total_input_tokens:  totalInputTok,
      total_output_tokens: totalOutputTok,
      total_tokens:        totalTok
    },
    status:             'completed',
    termination_reason: 'coordinator_synthesised_' + activeCnt + '_worker_output(s)'
  },

  execution_trace: {

    coordinator_decompose: {
      worker_count_decided: plan.worker_count,
      workers_active:       activeCnt,
      workers_skipped:      filterData.skipped_workers || [],
      rationale:            plan.decomposition_rationale,
      task_a:               plan.task_a,
      task_b:               plan.task_b || null,
      task_c:               plan.task_c || null,
      raw_output:           plan.coordinator_raw_output || '',
      token_estimate:       coordTok,
      parse_fallback_used:  plan.parse_fallback_used
    },

    workers: workerOutputs.map(w => ({
      worker:         w.worker,
      task_assigned:  w.task_assigned,
      output:         w.response,
      token_estimate: w.token_estimate
    })),

    synthesis: {
      output:         synthText,
      token_estimate: synthTok
    },

    structural_properties: {
      orchestration_type:  'AI-driven (LLM coordinator)',
      task_decomposition:  'dynamic — generated at runtime by Coordinator LLM',
      worker_prompts:      'dynamic — not hardcoded',
      worker_count:        'dynamic (1–3, decided by Coordinator at runtime)',
      bypass_mechanism:    'IF gate nodes with Set placeholder items for unused worker slots',
      merge_strategy:      'fixed 3-slot Merge node; skip placeholders filtered by code before synthesis',
      coordination_phases: 2,
      total_llm_calls:     llmCallsActual,
      ai_in_orchestration: true
    },

    llm_limitation: 'n8n Ollama node (lmChatOllama typeVersion 1) does not expose a temperature parameter. Temperature is governed by the Ollama server default (typically 0.8). To override it, set the value in the Ollama Modelfile or replace the native Ollama node with an HTTP Request node and pass temperature in the request body.'
  }

}}];
